import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW, STYLE } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const num = (v: unknown, d: number): number => (typeof v === "number" && isFinite(v) ? v : d);
const str = (v: unknown): string => (typeof v === "string" && v.trim() ? v.trim() : "");

const ImageOverlayTitle: React.FC<PrimitiveProps> = ({ anim, fps }) => {
  const frame = useCurrentFrame();
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = anim.params ?? {};

  const image = str(p.image) || str(p.src);
  const kicker = str(p.kicker);
  const title = str(anim.text);
  const maxOverlay = Math.max(0, Math.min(1, num(p.overlay, 0.7)));
  const fontSize = num(p.fontSize, 104);
  const zoom = num(p.zoom, 0.08);

  // image fades in over ~0.5s, then keeps a slow push-in for the whole layer
  const imgIn = interpolate(frame, [0, Math.round(fps * 0.5)], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const scale = 1 + zoom * (frame / total);

  // overlay darkens after the image has landed
  const darkStart = Math.round(fps * 0.45);
  const overlay = interpolate(frame, [darkStart, darkStart + Math.round(fps * 0.6)], [0, maxOverlay], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // text rises once the frame is dark enough to read on
  const textDelay = darkStart + Math.round(fps * 0.35);
  const rise = spring({ frame: frame - textDelay, fps, config: { damping: 200, mass: 0.7 } });
  const textY = interpolate(rise, [0, 1], [46, 0]);

  const kickerIn = interpolate(frame, [textDelay - Math.round(fps * 0.15), textDelay + Math.round(fps * 0.2)], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const gradientTitle =
    STYLE.headline === "gradient"
      ? {
          backgroundImage: headlineGradient(),
          WebkitBackgroundClip: "text" as const,
          backgroundClip: "text" as const,
          color: "transparent",
        }
      : { color: COLORS.textOnDark, textShadow: ENGRAVE_SHADOW };

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.papyrus, overflow: "hidden" }}>
      {image ? (
        <AbsoluteFill style={{ opacity: imgIn, transform: `scale(${scale})` }}>
          <Img src={image} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        </AbsoluteFill>
      ) : (
        <AbsoluteFill style={{ backgroundColor: COLORS.vellum, opacity: imgIn, transform: `scale(${scale})` }} />
      )}

      <AbsoluteFill style={{ backgroundColor: COLORS.ink, opacity: overlay }} />

      <AbsoluteFill
        style={{
          justifyContent: "flex-start",
          alignItems: "center",
          padding: "200px 90px 0 90px",
        }}
      >
        <div style={{ textAlign: "center", maxWidth: 900, transform: `translateY(${textY}px)`, opacity: rise }}>
          {kicker ? (
            <div
              style={{
                fontFamily: FONTS.mono,
                fontSize: 26,
                fontWeight: 600,
                letterSpacing: "0.3em",
                textTransform: "uppercase",
                color: COLORS.tealBright,
                marginBottom: 28,
                opacity: kickerIn,
              }}
            >
              {kicker}
            </div>
          ) : null}

          <div
            style={{
              fontFamily: FONTS.display,
              fontWeight: Math.max(FONTS.displayWeight, 700),
              fontSize,
              lineHeight: 0.9,
              letterSpacing: "-0.04em",
              textTransform: "uppercase",
              ...gradientTitle,
            }}
          >
            {title}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ImageOverlayTitle;
